const assert = require('assert');
const { execSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const DEFAULT_PR_BODY =
  'This PR was generated by [Poosh](https://github.com/BobTheBuidler/poosh) as part of a GitHub Actions workflow';
const REPO_SLUG = process.env.GITHUB_REPOSITORY || 'local/poosh';
const ACTION_FILE = path.resolve(__dirname, '..', '..', 'action.yml');
const ACTION_YAML = fs.readFileSync(ACTION_FILE, 'utf8');
const WORKFLOW_ERROR_REGEX =
  /create or update workflow|workflows? permission|workflows? scope/i;
const BRANCH_COLLISION_REGEX =
  /non-fast-forward|failed to push some refs|fetch first|updates were rejected/i;

const run = (cmd, cwd) => execSync(cmd, { cwd, stdio: 'pipe' });
const output = (cmd, cwd) => execSync(cmd, { cwd, encoding: 'utf8', stdio: 'pipe' }).trim();

const runWithOutput = (cmd, cwd) => {
  try {
    const stdout = execSync(cmd, { cwd, encoding: 'utf8', stdio: 'pipe' });
    return { ok: true, output: (stdout || '').trim() };
  } catch (error) {
    const stdout = error.stdout ? error.stdout.toString() : '';
    const stderr = error.stderr ? error.stderr.toString() : '';
    return { ok: false, output: `${stdout}\n${stderr}`.trim() };
  }
};

const hasStagedChanges = (repo) => {
  try {
    execSync('git diff --cached --quiet', { cwd: repo, stdio: 'ignore' });
    return false;
  } catch {
    return true;
  }
};

const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const dedentBlock = (block) => {
  const lines = block.replace(/\n$/, '').split('\n');
  const indents = lines
    .filter((line) => line.trim() !== '')
    .map((line) => (line.match(/^\s*/) || [''])[0].length);
  const minIndent = indents.length > 0 ? Math.min(...indents) : 0;
  return lines.map((line) => line.slice(minIndent)).join('\n');
};

const extractActionStepScript = (stepName) => {
  const lines = ACTION_YAML.split('\n');
  const nameLine = `- name: ${stepName}`;
  const stepStart = lines.findIndex((line) => line.trim() === nameLine);
  if (stepStart === -1) {
    throw new Error(`Unable to locate step '${stepName}' in action.yml`);
  }

  let runLine = -1;
  for (let idx = stepStart + 1; idx < lines.length; idx += 1) {
    const trimmed = lines[idx].trim();
    if (trimmed.startsWith('- name: ')) {
      break;
    }
    if (trimmed === 'run: |') {
      runLine = idx;
      break;
    }
  }
  if (runLine === -1) {
    throw new Error(`Step '${stepName}' does not contain a run block`);
  }

  const blockLines = [];
  for (let idx = runLine + 1; idx < lines.length; idx += 1) {
    const trimmed = lines[idx].trim();
    if (trimmed.startsWith('shell:')) {
      break;
    }
    blockLines.push(lines[idx]);
  }
  if (blockLines.length === 0) {
    throw new Error(`Step '${stepName}' has an empty run block`);
  }

  return dedentBlock(blockLines.join('\n'));
};

const extractBashFunction = (script, fnName) => {
  const lines = script.split('\n');
  const start = lines.findIndex((line) => line.trim() === `${fnName}() {`);
  if (start === -1) {
    throw new Error(`Function '${fnName}' not found in script`);
  }

  let end = -1;
  for (let idx = start + 1; idx < lines.length; idx += 1) {
    if (lines[idx].trim() === '}') {
      end = idx;
      break;
    }
  }
  if (end === -1) {
    throw new Error(`Function '${fnName}' has no closing brace`);
  }

  return lines.slice(start, end + 1).join('\n');
};

const resolveActionExpression = (expr, context) => {
  const trimmed = expr.trim();
  if (trimmed.startsWith('inputs.')) {
    const key = trimmed.slice('inputs.'.length);
    return context.inputs?.[key] ?? '';
  }

  const stepMatch = trimmed.match(/^steps\.([A-Za-z0-9_-]+)\.outputs\.([A-Za-z0-9._-]+)$/);
  if (stepMatch) {
    const [, stepId, outputKey] = stepMatch;
    return context.steps?.[stepId]?.outputs?.[outputKey] ?? '';
  }

  return '';
};

const renderActionScript = (script, context) =>
  script.replace(/\$\{\{\s*([^}]+?)\s*\}\}/g, (_, expr) =>
    String(resolveActionExpression(expr, context))
  );

const parseGithubOutput = (outputPath) => {
  if (!fs.existsSync(outputPath)) {
    return {};
  }

  const lines = fs.readFileSync(outputPath, 'utf8').split('\n');
  const outputs = {};

  for (let idx = 0; idx < lines.length; idx += 1) {
    const line = lines[idx];
    if (!line) {
      continue;
    }

    const heredocMatch = line.match(/^([^=]+)<<(\S+)$/);
    if (heredocMatch) {
      const [, key, delimiter] = heredocMatch;
      const body = [];
      idx += 1;
      while (idx < lines.length && lines[idx] !== delimiter) {
        body.push(lines[idx]);
        idx += 1;
      }
      outputs[key] = body.join('\n');
      continue;
    }

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) {
      continue;
    }
    const key = line.slice(0, eqIndex);
    const value = line.slice(eqIndex + 1);
    outputs[key] = value;
  }

  return outputs;
};

const runActionStep = ({ stepName, context = {}, cwd = process.cwd(), env = {} }) => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'poosh-action-step-'));
  const scriptPath = path.join(tempDir, 'step.sh');
  const outputPath = path.join(tempDir, 'github_output.txt');
  fs.writeFileSync(outputPath, '');

  const renderedScript = renderActionScript(extractActionStepScript(stepName), context);
  fs.writeFileSync(scriptPath, `${renderedScript}\n`);
  fs.chmodSync(scriptPath, 0o755);

  let ok = true;
  let stdout = '';
  let stderr = '';
  try {
    stdout = execSync(`bash "${scriptPath}"`, {
      cwd,
      env: { ...process.env, ...env, GITHUB_OUTPUT: outputPath },
      stdio: 'pipe',
      encoding: 'utf8',
    });
  } catch (error) {
    ok = false;
    stdout = error.stdout ? error.stdout.toString() : '';
    stderr = error.stderr ? error.stderr.toString() : '';
  }

  const outputs = parseGithubOutput(outputPath);
  fs.rmSync(tempDir, { recursive: true, force: true });

  return {
    ok,
    stdout: stdout.trim(),
    stderr: stderr.trim(),
    outputs,
  };
};

const defaultActionInputs = (overrides = {}) => ({
  'commit-message': 'test: local harness',
  'trigger-branch': 'main',
  'pr-branch': '',
  'pr-base': '',
  'trigger-pr-number': '',
  'pr-body': DEFAULT_PR_BODY,
  ...overrides,
});

const toActionInputs = (inputs = {}) =>
  defaultActionInputs({
    'commit-message': inputs.commitMessage || '',
    'trigger-branch': inputs.triggerBranch || '',
    'pr-branch': inputs.prBranch || '',
    'pr-base': inputs.prBase || '',
    'trigger-pr-number': inputs.triggerPrNumber || '',
    'pr-body': inputs.prBody || DEFAULT_PR_BODY,
  });

const ensureActionStepSuccess = (stepName, context, options = {}) => {
  const result = runActionStep({
    stepName,
    context,
    cwd: options.cwd || process.cwd(),
    env: options.env || {},
  });
  if (!result.ok) {
    const message = `${result.stdout}\n${result.stderr}`.trim();
    throw new Error(message || `${stepName} failed`);
  }
  return result.outputs;
};

const writeHook = (bareRepo, { rejectBranch, rejectWorkflowChanges } = {}) => {
  const hookPath = path.join(bareRepo, 'hooks', 'pre-receive');
  const hookLines = ['#!/bin/sh', 'set -e', 'while read old new ref; do'];

  if (rejectBranch) {
    hookLines.push(
      `  if [ "$ref" = "refs/heads/${rejectBranch}" ]; then`,
      '    echo "reject" >&2',
      '    exit 1',
      '  fi'
    );
  }

  if (rejectWorkflowChanges) {
    hookLines.push(
      '  if [ "$old" = "0000000000000000000000000000000000000000" ]; then',
      '    changed=$(git diff-tree --no-commit-id --name-only -r "$new" -- .github/workflows)',
      '  else',
      '    changed=$(git diff --name-only "$old" "$new" -- .github/workflows)',
      '  fi',
      '  if [ -n "$changed" ]; then',
      '    echo "refusing to allow a GitHub App to create or update workflow without workflows permission" >&2',
      '    exit 1',
      '  fi'
    );
  }

  hookLines.push('done', 'exit 0');
  fs.writeFileSync(hookPath, `${hookLines.join('\n')}\n`);
  fs.chmodSync(hookPath, 0o755);
};

const seedRemoteBranch = (repo, defaultBranch, branch) => {
  run(`git checkout ${defaultBranch}`, repo);
  run(`git checkout -b ${branch}`, repo);
  fs.writeFileSync(path.join(repo, 'seed.txt'), `${branch}\n`);
  run('git add seed.txt', repo);
  run(`git commit -q -m "seed ${branch}"`, repo);
  run(`git push origin ${branch}`, repo);
  run(`git checkout ${defaultBranch}`, repo);
  run(`git branch -D ${branch}`, repo);
};

const setupRepo = ({
  defaultBranch = 'main',
  rejectBranch,
  rejectWorkflowChanges,
  existingPrBranch,
} = {}) => {
  const base = fs.mkdtempSync(path.join(os.tmpdir(), 'poosh-test-'));
  run('git init --bare -q remote.git', base);
  const bare = path.join(base, 'remote.git');

  if (rejectBranch || rejectWorkflowChanges) {
    writeHook(bare, { rejectBranch, rejectWorkflowChanges });
  }

  const repo = path.join(base, 'repo');
  fs.mkdirSync(repo, { recursive: true });
  run('git init -q', repo);
  run('git config user.name "Test Bot"', repo);
  run('git config user.email "test@example.com"', repo);
  fs.writeFileSync(path.join(repo, 'file.txt'), 'hello\n');
  run('git add .', repo);
  run('git commit -q -m "init"', repo);
  run(`git branch -M ${defaultBranch}`, repo);
  run(`git remote add origin ${bare}`, repo);
  run(`git push -u origin ${defaultBranch}`, repo);

  if (existingPrBranch) {
    seedRemoteBranch(repo, defaultBranch, existingPrBranch);
  }

  return { base, repo };
};

const withRepo = (opts, fn) => {
  const ctx = setupRepo(opts);
  try {
    fn(ctx);
  } finally {
    fs.rmSync(ctx.base, { recursive: true, force: true });
  }
};

const remoteBranchExists = (repo, branch) => {
  try {
    execSync(`git ls-remote --exit-code --heads origin "refs/heads/${branch}"`, {
      cwd: repo,
      stdio: 'ignore',
    });
    return true;
  } catch {
    return false;
  }
};

const nextAvailablePrBranch = (repo, baseBranch, suffix = 0) => {
  let idx = suffix;
  let candidate = idx === 0 ? baseBranch : `${baseBranch}-${idx}`;

  while (remoteBranchExists(repo, candidate)) {
    idx += 1;
    candidate = `${baseBranch}-${idx}`;
  }

  return candidate;
};

const runPoosh = (repo, inputs) => {
  const actionInputs = toActionInputs(inputs);
  ensureActionStepSuccess("Validate 'commit-message'", { inputs: actionInputs });
  ensureActionStepSuccess("Validate 'trigger-branch'", { inputs: actionInputs });
  ensureActionStepSuccess("Validate 'pr-branch'", { inputs: actionInputs });
  ensureActionStepSuccess("Validate 'pr-base'", { inputs: actionInputs });

  const commitMessage = actionInputs['commit-message'];
  const triggerBranch = actionInputs['trigger-branch'];
  const outputs = {
    triggerBranch,
    commitSha: '',
    prUrl: '',
    prNumber: '',
  };

  const currentBranch = output('git rev-parse --abbrev-ref HEAD', repo);
  if (currentBranch !== triggerBranch && remoteBranchExists(repo, triggerBranch)) {
    run(`git fetch origin ${triggerBranch}:${triggerBranch}`, repo);
    run(`git checkout ${triggerBranch}`, repo);
    run(`git pull origin ${triggerBranch}`, repo);
  }

  run('git add .', repo);
  if (!hasStagedChanges(repo)) {
    return outputs;
  }

  run('git config --local user.name "github-actions[bot]"', repo);
  run('git config --local user.email "github-actions[bot]@users.noreply.github.com"', repo);
  const safeMessage = commitMessage.replace(/"/g, '\\"');
  run(`git commit -m "${safeMessage}"`, repo);
  outputs.commitSha = output('git rev-parse HEAD', repo);

  const workflowChanges = output('git show --name-only --pretty="" HEAD -- .github/workflows', repo) !== '';
  const pushResult = runWithOutput(`git push origin "HEAD:${triggerBranch}"`, repo);
  const workflowPushDenied = !pushResult.ok && WORKFLOW_ERROR_REGEX.test(pushResult.output);

  if (pushResult.ok) {
    return outputs;
  }

  let prBranch = actionInputs['pr-branch'];
  let autoPrBranch = false;
  let prBranchBase = '';

  if (!prBranch) {
    prBranchBase = `poosh/${triggerBranch}`;
    prBranch = nextAvailablePrBranch(repo, prBranchBase);
    autoPrBranch = true;
  } else if (!prBranch.includes('/')) {
    prBranch = `poosh/${prBranch}`;
  }

  const resolveBaseSha = () => {
    let baseSha = '';
    const firstTry = runWithOutput('git rev-parse HEAD~1', repo);
    if (firstTry.ok) {
      baseSha = firstTry.output;
    }
    const shallow = runWithOutput('git rev-parse --is-shallow-repository', repo);
    if (!baseSha && shallow.ok && shallow.output === 'true') {
      const deepenBranch = runWithOutput(`git fetch --deepen=1 origin ${triggerBranch}`, repo);
      if (!deepenBranch.ok) {
        runWithOutput('git fetch --deepen=1 origin', repo);
      }
      const retry = runWithOutput('git rev-parse HEAD~1', repo);
      if (retry.ok) {
        baseSha = retry.output;
      }
    }
    if (!baseSha) {
      throw new Error(
        'Unable to resolve the parent commit to strip workflow changes. Ensure checkout fetch-depth is at least 2.'
      );
    }
    return baseSha;
  };

  const stripWorkflowsAndCommit = () => {
    const origSha = output('git rev-parse HEAD', repo);
    const baseSha = resolveBaseSha();

    run(`git checkout -B ${prBranch} ${baseSha}`, repo);
    run(`git restore --source ${origSha} --staged --worktree .`, repo);
    run(`git restore --source ${baseSha} --staged --worktree .github/workflows`, repo);

    if (!hasStagedChanges(repo)) {
      return false;
    }

    run(`git commit -m "${safeMessage}"`, repo);
    outputs.commitSha = output('git rev-parse HEAD', repo);
    return true;
  };

  const pushPrBranch = () => {
    let collisionRetries = 0;

    while (true) {
      const prPush = runWithOutput(`git push origin ${prBranch}`, repo);
      if (prPush.ok) {
        return { ok: true, output: '' };
      }

      if (
        autoPrBranch &&
        BRANCH_COLLISION_REGEX.test(prPush.output) &&
        remoteBranchExists(repo, prBranch)
      ) {
        collisionRetries += 1;
        if (collisionRetries > 20) {
          return prPush;
        }

        prBranch = nextAvailablePrBranch(repo, prBranchBase, collisionRetries);
        run(`git checkout -B ${prBranch}`, repo);
        continue;
      }

      return prPush;
    }
  };

  if (workflowPushDenied && workflowChanges) {
    if (!stripWorkflowsAndCommit()) {
      return outputs;
    }
  } else {
    run(`git checkout -b ${prBranch}`, repo);
  }

  const prPush = pushPrBranch();
  if (!prPush.ok) {
    if (WORKFLOW_ERROR_REGEX.test(prPush.output) && workflowChanges) {
      if (!stripWorkflowsAndCommit()) {
        return outputs;
      }

      const retryPush = pushPrBranch();
      if (!retryPush.ok) {
        throw new Error(retryPush.output || 'push failed');
      }
    } else {
      throw new Error(prPush.output || 'push failed');
    }
  }

  const prBase = actionInputs['pr-base'] || triggerBranch;
  const composeOutputs = ensureActionStepSuccess(
    'Compose PR body',
    {
      inputs: actionInputs,
    },
    {
      env: {
        GITHUB_REPOSITORY: REPO_SLUG,
      },
    }
  );

  outputs.prUrl = `https://example.com/${prBranch}`;
  outputs.prNumber = '1';
  outputs.prBase = prBase;
  outputs.prBranch = prBranch;
  outputs.prBody = composeOutputs.body;

  return outputs;
};

const addFileChange = (repo) => {
  fs.appendFileSync(path.join(repo, 'file.txt'), 'change\n');
};

const addWorkflowChange = (repo) => {
  const workflowsDir = path.join(repo, '.github', 'workflows');
  fs.mkdirSync(workflowsDir, { recursive: true });
  fs.writeFileSync(path.join(workflowsDir, 'ci.yml'), 'name: ci\n');
};

const assertWorkflowFilesStripped = (repo, prBranch) => {
  run(`git fetch origin ${prBranch}`, repo);

  const workflowDiff = output(
    `git diff --name-only origin/${prBranch}~1 origin/${prBranch} -- .github/workflows`,
    repo
  );
  assert.strictEqual(workflowDiff, '');

  const fileDiff = output(
    `git diff --name-only origin/${prBranch}~1 origin/${prBranch} -- file.txt`,
    repo
  );
  assert.strictEqual(fileDiff, 'file.txt');
};

const assertActionStepFails = ({ stepName, inputs, pattern }) => {
  const result = runActionStep({
    stepName,
    context: {
      inputs: defaultActionInputs(inputs),
    },
  });
  assert.strictEqual(result.ok, false);
  assert.match(`${result.stdout}\n${result.stderr}`, pattern);
};

const runResolveBaseShaShallowRecovery = () => {
  const createPrScript = renderActionScript(
    extractActionStepScript('Create PR branch and push (if direct push failed)'),
    {
      inputs: defaultActionInputs({ 'trigger-branch': 'main' }),
      steps: {
        check_changes: {
          outputs: {
            changed: 'true',
            workflow_changes: 'true',
          },
        },
        try_push: {
          outputs: {
            push_success: 'false',
            workflow_push_denied: 'true',
          },
        },
      },
    }
  );
  const resolveBaseShaFn = extractBashFunction(createPrScript, 'resolve_base_sha');

  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'poosh-base-sha-'));
  const shimDir = path.join(tempDir, 'shim');
  fs.mkdirSync(shimDir, { recursive: true });

  const shimPath = path.join(shimDir, 'git');
  const shimLog = path.join(tempDir, 'git.log');
  const shimCount = path.join(tempDir, 'head1.count');
  fs.writeFileSync(
    shimPath,
    `#!/bin/sh
set -eu
echo "$*" >> "$GIT_SHIM_LOG"
if [ "$1" = "rev-parse" ] && [ "\${2:-}" = "HEAD~1" ]; then
  count=0
  if [ -f "$GIT_SHIM_COUNT" ]; then
    count=$(cat "$GIT_SHIM_COUNT")
  fi
  count=$((count + 1))
  echo "$count" > "$GIT_SHIM_COUNT"
  if [ "$count" -eq 1 ]; then
    exit 1
  fi
  echo "base-sha-123"
  exit 0
fi
if [ "$1" = "rev-parse" ] && [ "\${2:-}" = "--is-shallow-repository" ]; then
  echo "true"
  exit 0
fi
if [ "$1" = "fetch" ] && [ "\${2:-}" = "--deepen=1" ] && [ "\${3:-}" = "origin" ]; then
  exit 0
fi
echo "unexpected git command: $*" >&2
exit 1
`
  );
  fs.chmodSync(shimPath, 0o755);

  const scriptPath = path.join(tempDir, 'run.sh');
  const outputPath = path.join(tempDir, 'github_output.txt');
  fs.writeFileSync(
    scriptPath,
    `set -e
${resolveBaseShaFn}
resolved="$(resolve_base_sha | tail -n 1)"
echo "resolved=$resolved" >> "$GITHUB_OUTPUT"
`
  );
  fs.chmodSync(scriptPath, 0o755);
  fs.writeFileSync(outputPath, '');

  try {
    execSync(`bash "${scriptPath}"`, {
      cwd: tempDir,
      env: {
        ...process.env,
        PATH: `${shimDir}:${process.env.PATH || ''}`,
        GITHUB_OUTPUT: outputPath,
        GIT_SHIM_LOG: shimLog,
        GIT_SHIM_COUNT: shimCount,
      },
      stdio: 'pipe',
    });

    const outputs = parseGithubOutput(outputPath);
    assert.strictEqual(outputs.resolved, 'base-sha-123');

    const lines = fs
      .readFileSync(shimLog, 'utf8')
      .split('\n')
      .map((line) => line.trim())
      .filter(Boolean);
    const headChecks = lines.filter((line) => line === 'rev-parse HEAD~1').length;
    assert.strictEqual(headChecks, 2);
    assert.ok(lines.includes('rev-parse --is-shallow-repository'));
    assert.ok(lines.includes('fetch --deepen=1 origin main'));
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
};

const runTest = (name, fn) => {
  try {
    fn();
  } catch (error) {
    error.message = `${name} failed: ${error.message}`;
    throw error;
  }
};

const tests = [
  [
    'testNoChanges',
    () =>
      withRepo({}, ({ repo }) => {
        const outputs = runPoosh(repo, {
          commitMessage: 'test: no changes',
          triggerBranch: 'main',
        });

        assert.strictEqual(outputs.triggerBranch, 'main');
        assert.strictEqual(outputs.commitSha, '');
        assert.strictEqual(outputs.prUrl, '');
      }),
  ],
  [
    'testPushSuccess',
    () =>
      withRepo({}, ({ repo }) => {
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: push success',
          triggerBranch: 'main',
        });

        assert.ok(outputs.commitSha);
        assert.strictEqual(outputs.prUrl, '');
      }),
  ],
  [
    'testPushFailureCreatesPr',
    () =>
      withRepo({ rejectBranch: 'blocked' }, ({ repo }) => {
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: pr fallback',
          triggerBranch: 'blocked',
          prBranch: 'custom',
          prBase: 'main',
          triggerPrNumber: '123',
        });

        assert.ok(outputs.commitSha);
        assert.ok(outputs.prUrl);
        assert.strictEqual(outputs.prBase, 'main');
        assert.strictEqual(outputs.prBranch, 'poosh/custom');
        assert.ok(outputs.prBody.includes('[Triggered by PR #123]'));
        assert.ok(outputs.prBody.includes('/pull/123'));
        assert.ok(remoteBranchExists(repo, outputs.prBranch));
      }),
  ],
  [
    'testWorkflowPermissionFallback',
    () =>
      withRepo({ rejectWorkflowChanges: true }, ({ repo }) => {
        addWorkflowChange(repo);
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: workflow fallback',
          triggerBranch: 'main',
        });

        assert.ok(outputs.prUrl);
        assert.ok(outputs.prBody.includes('Triggered by recent changes on branch'));
        assert.ok(remoteBranchExists(repo, outputs.prBranch));
        assertWorkflowFilesStripped(repo, outputs.prBranch);
      }),
  ],
  [
    'testFallbackBranchCollision',
    () =>
      withRepo({ rejectBranch: 'blocked', existingPrBranch: 'poosh/blocked' }, ({ repo }) => {
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: fallback collision',
          triggerBranch: 'blocked',
        });

        assert.strictEqual(outputs.prBranch, 'poosh/blocked-1');
        assert.ok(remoteBranchExists(repo, outputs.prBranch));
        assert.ok(remoteBranchExists(repo, 'poosh/blocked'));
      }),
  ],
  [
    'testWorkflowFallbackBranchCollision',
    () =>
      withRepo({ rejectWorkflowChanges: true, existingPrBranch: 'poosh/main' }, ({ repo }) => {
        addWorkflowChange(repo);
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: workflow collision fallback',
          triggerBranch: 'main',
        });

        assert.strictEqual(outputs.prBranch, 'poosh/main-1');
        assert.ok(remoteBranchExists(repo, outputs.prBranch));
        assert.ok(remoteBranchExists(repo, 'poosh/main'));
        assertWorkflowFilesStripped(repo, outputs.prBranch);
      }),
  ],
  [
    'testInvalidTriggerBranch',
    () => {
      assert.throws(
        () =>
          withRepo({}, ({ repo }) =>
            runPoosh(repo, {
              commitMessage: 'test: invalid branch',
              triggerBranch: 'bad^branch',
            })
          ),
        /trigger-branch/
      );
    },
  ],
  [
    'testInvalidCommitMessage',
    () => {
      assertActionStepFails({
        stepName: "Validate 'commit-message'",
        inputs: { 'commit-message': '   ' },
        pattern: /'commit-message' is required and must be a non-empty string/,
      });
    },
  ],
  [
    'testInvalidTriggerBranchWhitespace',
    () => {
      assertActionStepFails({
        stepName: "Validate 'trigger-branch'",
        inputs: { 'trigger-branch': ' \t ' },
        pattern: /'trigger-branch' is required and must be a non-empty string/,
      });
    },
  ],
  [
    'testInvalidPrBranch',
    () => {
      assertActionStepFails({
        stepName: "Validate 'pr-branch'",
        inputs: { 'pr-branch': 'bad^branch' },
        pattern: /'pr-branch' contains invalid characters/,
      });
    },
  ],
  [
    'testInvalidPrBase',
    () => {
      assertActionStepFails({
        stepName: "Validate 'pr-base'",
        inputs: { 'pr-base': 'bad^base' },
        pattern: /'pr-base' contains invalid characters/,
      });
    },
  ],
  [
    'testWorkflowOnlyChangesNoFallbackPush',
    () =>
      withRepo({ rejectWorkflowChanges: true }, ({ repo }) => {
        addWorkflowChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: workflow only fallback',
          triggerBranch: 'main',
        });

        assert.strictEqual(outputs.prUrl, '');
        assert.strictEqual(outputs.prNumber, '');
        assert.strictEqual(outputs.prBranch, undefined);
        assert.strictEqual(remoteBranchExists(repo, 'poosh/main'), false);
        run('git fetch origin main', repo);
        const remoteWorkflowFiles = output(
          'git ls-tree -r --name-only origin/main -- .github/workflows',
          repo
        );
        assert.strictEqual(remoteWorkflowFiles, '');
      }),
  ],
  [
    'testPrBranchWithSlashNotPrefixed',
    () =>
      withRepo({ rejectBranch: 'blocked' }, ({ repo }) => {
        addFileChange(repo);
        const outputs = runPoosh(repo, {
          commitMessage: 'test: slash branch',
          triggerBranch: 'blocked',
          prBranch: 'feature/custom',
          prBase: 'main',
        });

        assert.strictEqual(outputs.prBranch, 'feature/custom');
        assert.ok(remoteBranchExists(repo, 'feature/custom'));
        assert.strictEqual(remoteBranchExists(repo, 'poosh/feature/custom'), false);
      }),
  ],
  [
    'testComposePrBodyWithTriggerPrNumber',
    () => {
      const result = runActionStep({
        stepName: 'Compose PR body',
        context: {
          inputs: defaultActionInputs({
            'trigger-branch': 'main',
            'trigger-pr-number': '42',
          }),
        },
        env: {
          GITHUB_REPOSITORY: 'owner/repo',
        },
      });

      assert.strictEqual(result.ok, true);
      assert.ok(
        result.outputs.body.includes(
          '[Triggered by PR #42](https://github.com/owner/repo/pull/42)'
        )
      );
      assert.strictEqual(result.outputs.body.includes('Triggered by recent changes on branch'), false);
    },
  ],
  [
    'testComposePrBodyWithoutTriggerPrNumber',
    () => {
      const result = runActionStep({
        stepName: 'Compose PR body',
        context: {
          inputs: defaultActionInputs({
            'trigger-branch': 'feature/xyz',
            'trigger-pr-number': '',
          }),
        },
        env: {
          GITHUB_REPOSITORY: 'owner/repo',
        },
      });

      assert.strictEqual(result.ok, true);
      assert.ok(result.outputs.body.includes('Triggered by recent changes on branch `feature/xyz`'));
      assert.ok(result.outputs.body.includes('https://github.com/owner/repo/tree/feature/xyz'));
      assert.strictEqual(result.outputs.body.includes('Triggered by PR #'), false);
    },
  ],
  [
    'testSetOutputsWiring',
    () => {
      const fullResult = runActionStep({
        stepName: 'Set outputs',
        context: {
          inputs: defaultActionInputs({ 'trigger-branch': 'release/main' }),
          steps: {
            commit_changes: {
              outputs: {
                'commit-sha': 'abc123',
              },
            },
            create_pr: {
              outputs: {
                'pull-request-url': 'https://example.test/pr/1',
                'pull-request-number': '1',
              },
            },
          },
        },
      });
      assert.strictEqual(fullResult.ok, true);
      assert.strictEqual(fullResult.outputs['trigger-branch'], 'release/main');
      assert.strictEqual(fullResult.outputs['commit-sha'], 'abc123');
      assert.strictEqual(fullResult.outputs['pr-url'], 'https://example.test/pr/1');
      assert.strictEqual(fullResult.outputs['pr-number'], '1');

      const minimalResult = runActionStep({
        stepName: 'Set outputs',
        context: {
          inputs: defaultActionInputs({ 'trigger-branch': 'release/main' }),
          steps: {
            commit_changes: {
              outputs: {
                'commit-sha': '',
              },
            },
            create_pr: {
              outputs: {
                'pull-request-url': '',
                'pull-request-number': '',
              },
            },
          },
        },
      });
      assert.strictEqual(minimalResult.ok, true);
      assert.strictEqual(minimalResult.outputs['trigger-branch'], 'release/main');
      assert.strictEqual(Object.prototype.hasOwnProperty.call(minimalResult.outputs, 'commit-sha'), false);
      assert.strictEqual(Object.prototype.hasOwnProperty.call(minimalResult.outputs, 'pr-url'), false);
      assert.strictEqual(Object.prototype.hasOwnProperty.call(minimalResult.outputs, 'pr-number'), false);
    },
  ],
  [
    'testResolveBaseShaShallowRecovery',
    () => {
      runResolveBaseShaShallowRecovery();
    },
  ],
];

const main = () => {
  for (const [name, fn] of tests) {
    runTest(name, fn);
  }

  console.log('All tests passed.');
};

main();